#!/usr/bin/env bash
# =============================================================================
#  apply-floor-catalog.sh  ·  EcoWoods
#  Installs the 12-product hardwood Floor Catalog (36 images, room/detail/
#  lifestyle triptych + lightbox) into apps/web. Idempotent & re-runnable.
#
#  USAGE (from repo root, on a FRESH branch created AFTER this file exists):
#     git checkout -b feat/floor-catalog
#     bash apply-floor-catalog.sh
#     pnpm --filter web dev     # test locally in Codespaces
# =============================================================================
set -euo pipefail

# ---- 0. guard: must be repo root -------------------------------------------
if [[ ! -f pnpm-workspace.yaml || ! -d apps/web ]]; then
  echo "✗ Run this from the repo root (pnpm-workspace.yaml + apps/web must exist)."; exit 1
fi
echo "▸ EcoWoods Floor Catalog installer"

WEB=apps/web
APP=$WEB/app

# ---- 1. images: unzip public/gallery.zip -> apps/web/public/gallery ---------
mkdir -p "$WEB/public/gallery"
if [[ -f public/gallery.zip ]]; then
  echo "▸ Extracting images from public/gallery.zip ..."
  tmp=$(mktemp -d)
  unzip -o -q public/gallery.zip -d "$tmp"
  # zip contains gallery/*.webp (+ macOS __MACOSX junk we skip)
  find "$tmp" -path '*__MACOSX*' -prune -o -name '*.webp' -print \
    -exec cp {} "$WEB/public/gallery/" \; >/dev/null
  rm -rf "$tmp"
fi
COUNT=$(find "$WEB/public/gallery" -name '*.webp' | wc -l | tr -d ' ')
echo "  → $COUNT webp images in $WEB/public/gallery"
if [[ "$COUNT" -lt 36 ]]; then
  echo "  ⚠ expected 36 images. Make sure public/gallery.zip is committed & present."
fi

# ---- 2. write data + component (base64, exact bytes) -----------------------
mkdir -p "$APP/data" "$APP/components"
echo "▸ Writing data/floors.ts"
base64 -d > "$APP/data/floors.ts" <<'B64_FLOORS'

B64_FLOORS
echo "▸ Writing components/FloorCatalog.tsx"
base64 -d > "$APP/components/FloorCatalog.tsx" <<'B64_COMP'

B64_COMP

# ---- 3. patch page.tsx (idempotent, via node) ------------------------------
echo "▸ Wiring page.tsx (import + render + section head)"
node - "$APP/page.tsx" <<'NODE'
const fs = require('fs');
const p = process.argv[2];
let s = fs.readFileSync(p, 'utf8');
const imp = "import PortfolioGallery from './components/PortfolioGallery';";
if (!s.includes("import FloorCatalog")) {
  if (s.includes(imp)) s = s.replace(imp, imp + "\nimport FloorCatalog from './components/FloorCatalog';");
  else s = "import FloorCatalog from './components/FloorCatalog';\n" + s;
}
s = s.replace('<PortfolioGallery items={galleryItems} />', '<FloorCatalog />');
s = s.replace('<span className="eyebrow">The Work</span>', '<span className="eyebrow">The Collection</span>');
s = s.replace(
  'Toronto&rsquo;s living rooms, <span className="serif-italic">our portfolio.</span>',
  'Twelve floors, <span className="serif-italic">endless rooms.</span>');
s = s.replace(
  'A curated sample of projects completed across the GTA in the last twelve months.',
  'The species and finishes we install across the GTA — tap any floor to see the grain up close and the room it belongs in.');
fs.writeFileSync(p, s);
console.log('  → FloorCatalog import:', s.includes('import FloorCatalog'));
console.log('  → render swapped   :', s.includes('<FloorCatalog />') && !s.includes('<PortfolioGallery items'));
NODE

# ---- 4. CSS block (idempotent, between markers) ----------------------------
echo "▸ Inserting scoped CSS into app/globals.css"
CSS_TMP=$(mktemp)
base64 -d > "$CSS_TMP" <<'B64_CSS'

B64_CSS
node - "$APP/globals.css" "$CSS_TMP" <<'NODE'
const fs = require('fs');
const [gPath, cssPath] = process.argv.slice(2);
let s = fs.readFileSync(gPath, 'utf8');
const block = fs.readFileSync(cssPath, 'utf8');
s = s.replace(/\n?\/\* === EW:FLOOR-CATALOG START === \*\/[\s\S]*?\/\* === EW:FLOOR-CATALOG END === \*\/\n?/g, '\n');
if (!s.endsWith('\n')) s += '\n';
s += '\n' + block.trim() + '\n';
fs.writeFileSync(gPath, s);
console.log('  → CSS markers present:', s.includes('EW:FLOOR-CATALOG START'));
NODE
rm -f "$CSS_TMP"

echo ""
echo "✅ Done. The old PortfolioGallery/galleryItems remain in the repo (unused, harmless)."
echo "   Next:  pnpm --filter web dev   → open /#gallery and tap a floor."
